#pragma once

namespace Slic3r::GUI::JusPrin::Updates {

// JusPrin's own version: what Preferences shows and what the update check
// compares with the version in each JusPrin release tag. It is separate
// from SoftFever_VERSION, OrcaSlicer's version, which this build keeps
// because 3MF projects, profile updates, the user_backup-v<version> folder
// and AppConfig's upgrade logic all read it.
inline constexpr char kVersion[] = "2.0.0";

} // namespace Slic3r::GUI::JusPrin::Updates

#pragma once

// Reads JusPrin's release list as GitHub's REST API returns it
// (GET /repos/TheSpaghettiDetective/JusPrin/releases). GUI-free.

#include <nlohmann/json.hpp>

#include <optional>
#include <string>

namespace Slic3r::GUI::JusPrin::Updates {

struct Release
{
    std::string version;   // "2.1.0", from the tag
    std::string url;       // the release page
    std::string published; // when it was published, as GitHub gives it
};

// The version a release tag names: "v2.1.0" and "jusprin/v2.1.0" both give
// "2.1.0". Empty when the tag names no version, as "nightly-builds" does.
std::string tag_version(const std::string& tag);

// The newest release in `releases` that is newer than `running`. Drafts are
// skipped, and so are pre-releases unless `running` is itself one: someone
// on a test build hears about newer test builds, and nobody else does.
// Throws when `releases` is not a list of GitHub releases.
std::optional<Release> newer_release(const nlohmann::json& releases, const std::string& running);

} // namespace Slic3r::GUI::JusPrin::Updates

#include "ReleaseFeed.hpp"

#include "libslic3r/Semver.hpp"

#include <boost/algorithm/string/predicate.hpp>

#include <stdexcept>

namespace Slic3r::GUI::JusPrin::Updates {

std::string tag_version(const std::string& tag)
{
    std::string version = tag;
    // JusPrin 1.4.0 was tagged jusprin/v1.4.0, the releases before it v1.3.0.
    if (boost::starts_with(version, "jusprin/"))
        version.erase(0, 8);
    if (boost::starts_with(version, "v"))
        version.erase(0, 1);
    return Semver::parse(version) ? version : std::string();
}

std::optional<Release> newer_release(const nlohmann::json& releases, const std::string& running)
{
    if (!releases.is_array())
        throw std::invalid_argument("a GitHub release list is an array");
    const Semver current(running);
    const bool   test_build = current.prerelease() != nullptr;

    std::optional<Release> newest;
    Semver                 newest_version = current;
    for (const nlohmann::json& release : releases) {
        if (release.at("draft").get<bool>())
            continue;
        if (release.at("prerelease").get<bool>() && !test_build)
            continue;
        const std::string version = tag_version(release.at("tag_name").get<std::string>());
        if (version.empty())
            continue;
        const Semver candidate(version);
        if (!(newest_version < candidate))
            continue;
        newest_version = candidate;
        newest = Release{version, release.at("html_url").get<std::string>(), release.value("published_at", std::string())};
    }
    return newest;
}

} // namespace Slic3r::GUI::JusPrin::Updates

#pragma once

// What JusPrin's update check remembers between runs, and when it runs
// next. Kept in AppConfig; GUI-free.

#include "ReleaseFeed.hpp"

#include <ctime>
#include <optional>
#include <string>

namespace Slic3r { class AppConfig; }

namespace Slic3r::GUI::JusPrin::Updates {

// "New JusPrin versions" in Preferences > Updates: "0" turns the daily
// check off. Check now still works.
inline constexpr char kAutoCheckKey[] = "jusprin_update_check";
// Where the release list is read from, for tests against a local server.
inline constexpr char kFeedUrlKey[] = "jusprin_update_feed_url";

struct UpdateRecord
{
    std::time_t            last_attempt{0}; // 0: never
    std::time_t            last_success{0};
    bool                   last_failed{false};
    std::optional<Release> available; // newer than the running version
};

bool auto_check_enabled(const AppConfig& config);

// A release remembered from an earlier run is dropped once the running
// version has caught up with it.
UpdateRecord load_record(const AppConfig& config, const std::string& running);
void         save_success(AppConfig& config, std::time_t now, const std::optional<Release>& available);
void         save_failure(AppConfig& config, std::time_t now);

// Whether the daily check should run: a day after the last attempt and, at
// startup, also when the last attempt failed.
bool check_due(const UpdateRecord& record, std::time_t now, bool at_startup);

} // namespace Slic3r::GUI::JusPrin::Updates

#include "UpdateRecord.hpp"

#include "libslic3r/AppConfig.hpp"
#include "libslic3r/Semver.hpp"

namespace Slic3r::GUI::JusPrin::Updates {

namespace {

constexpr char        kLastAttemptKey[] = "jusprin_update_last_attempt";
constexpr char        kLastSuccessKey[] = "jusprin_update_last_success";
constexpr char        kLastFailedKey[]  = "jusprin_update_last_failed";
constexpr char        kVersionKey[]     = "jusprin_update_version";
constexpr char        kUrlKey[]         = "jusprin_update_url";
constexpr char        kPublishedKey[]   = "jusprin_update_published";
constexpr std::time_t kDay              = 24 * 60 * 60;

std::time_t read_time(const AppConfig& config, const char* key)
{
    const std::string value = config.get(key);
    return value.empty() ? 0 : static_cast<std::time_t>(std::stoll(value));
}

} // namespace

bool auto_check_enabled(const AppConfig& config) { return config.get(kAutoCheckKey) != "0"; }

UpdateRecord load_record(const AppConfig& config, const std::string& running)
{
    UpdateRecord record;
    record.last_attempt = read_time(config, kLastAttemptKey);
    record.last_success = read_time(config, kLastSuccessKey);
    record.last_failed  = config.get(kLastFailedKey) == "1";
    const std::string version = config.get(kVersionKey);
    if (const auto parsed = Semver::parse(version); parsed && Semver(running) < *parsed)
        record.available = Release{version, config.get(kUrlKey), config.get(kPublishedKey)};
    return record;
}

void save_success(AppConfig& config, std::time_t now, const std::optional<Release>& available)
{
    config.set(kLastAttemptKey, std::to_string(now));
    config.set(kLastSuccessKey, std::to_string(now));
    config.set(kLastFailedKey, "0");
    config.set(kVersionKey, available ? available->version : std::string());
    config.set(kUrlKey, available ? available->url : std::string());
    config.set(kPublishedKey, available ? available->published : std::string());
}

void save_failure(AppConfig& config, std::time_t now)
{
    config.set(kLastAttemptKey, std::to_string(now));
    config.set(kLastFailedKey, "1");
}

bool check_due(const UpdateRecord& record, std::time_t now, bool at_startup)
{
    if (at_startup && record.last_failed)
        return true;
    return now - record.last_attempt >= kDay;
}

} // namespace Slic3r::GUI::JusPrin::Updates

