// Sets app-section keys in a JusPrin2.conf and rewrites its MD5 line, the
// way AppConfig::save() does (MD5 of the JSON as written, "\n" line ends).
// Usage: node set-conf.js <conf> key=value ...   (value "" erases the key)
const fs = require('fs');
const crypto = require('crypto');
const [file, ...pairs] = process.argv.slice(2);
const text = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
const config = JSON.parse(text.slice(0, text.lastIndexOf('}') + 1));
for (const pair of pairs) {
  const at = pair.indexOf('=');
  const key = pair.slice(0, at);
  const value = pair.slice(at + 1);
  if (value === '') delete config.app[key];
  else config.app[key] = value;
}
const json = JSON.stringify(config, null, '\t');
const md5 = crypto.createHash('md5').update(json, 'utf8').digest('hex').toUpperCase();
fs.writeFileSync(file, (json + '\n# MD5 checksum ' + md5 + '\n').replace(/\n/g, '\r\n'));

