// A small WebView2 DevTools driver.
//   node cdp.js list
//   node cdp.js eval <title-or-url substring> <javascript>
//   node cdp.js shot <title-or-url substring> <png file>
const fs = require('fs');
const [command, match, arg] = process.argv.slice(2);
const port = process.env.CDP_PORT || '9222';

async function targets() {
  const response = await fetch(`http://127.0.0.1:${port}/json`);
  return (await response.json()).filter((t) => t.type === 'page');
}

function session(url) {
  const ws = new WebSocket(url);
  let next = 0;
  const pending = new Map();
  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);
    if (message.id !== undefined && pending.has(message.id)) {
      pending.get(message.id)(message);
      pending.delete(message.id);
    }
  };
  const ready = new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  return {
    ready,
    send: (method, params = {}) => new Promise((resolve) => {
      const id = ++next;
      pending.set(id, resolve);
      ws.send(JSON.stringify({ id, method, params }));
    }),
    close: () => ws.close(),
  };
}

(async () => {
  const all = await targets();
  if (command === 'list') {
    for (const t of all) console.log(`${t.title} | ${t.url.slice(0, 100)}`);
    return;
  }
  const target = all.find((t) => t.title.includes(match) || t.url.includes(match));
  if (!target) throw new Error(`no page matches ${match}: ${all.map((t) => t.title).join(', ')}`);
  const s = session(target.webSocketDebuggerUrl);
  await s.ready;
  if (command === 'eval') {
    const result = await s.send('Runtime.evaluate', { expression: arg, awaitPromise: true, returnByValue: true });
    console.log(JSON.stringify(result.result?.result?.value ?? result.result));
  } else if (command === 'shot') {
    const result = await s.send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(arg, Buffer.from(result.result.data, 'base64'));
    console.log(`saved ${arg}`);
  }
  s.close();
})().catch((error) => { console.error(error.message); process.exit(1); });

